package tarea14;
import javax.swing.JOptionPane;
public class boletin02_11_b_doWhile {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int producto, i;
		producto = 1;
		i = 1;
		do {
			producto = producto * i;
			i = i + 2;
			} while (i <= 20);
		

	}

}
